#include "../src/game/flying_enemies.hpp"
#include <cassert>
int main(int argc,char**argv){assert(argc==2);shin::AssetStore a(argv[1]);shin::IndexedSurface f(640,480);shin::PlayerPayload p;p.at(8)=300;p.at(12)=200;p.at(0x10)=100;shin::game::FlyingEnemyManager m;m.spawn(0x37,300,100,1);m.spawn(0x37,300,100,1);assert(m.targets().size()==1);for(int i=0;i<58;++i)m.tick(0,0,p,a,f);assert(m.projectile_events.size()==1&&m.projectile_events[0].callback==0x42cc00);auto*e=m.targets().front();assert(m.hurt(*e));assert(!m.hurt(*e));for(int i=0;i<10;++i)m.tick(0,0,p,a,f);assert(m.targets().empty());m.spawn(0x37,300,100,1);assert(m.targets().empty());m.clear();m.spawn(0x38,300,100,2);for(int i=0;i<75;++i)m.tick(0,0,p,a,f);assert(m.projectile_events.size()==1&&m.projectile_events[0].callback==0x41e610);m.clear();m.spawn(0x39,300,100,3);for(int i=0;i<240;++i)m.tick(0,0,p,a,f);assert(m.projectile_events.empty());m.clear();m.spawn(0x3c,300,100,4);m.tick(0,0,p,a,f);e=m.targets().front();assert(e->at(4)==299&&e->at(8)==102);m.clear();m.spawn(0x40,300,100,5);for(int i=0;i<21;++i)m.tick(0,0,p,a,f);assert(m.targets().front()->at(0x48)==-7);}
